## Code Example
```typescript
interface Parser {
  parse(input: AsyncIterable<Uint8Array>): AsyncIterable<Record<string, unknown>>;
}

type ParserFactory = () => Parser;

class Registry {
  private factories = new Map<string, ParserFactory>();

  register(extension: string, factory: ParserFactory): void {
    this.factories.set(extension.toLowerCase(), factory);
  }

  getParser(extension: string): Parser | undefined {
    return this.factories.get(extension.toLowerCase())?.();
  }
}

// Usage example
const registry = new Registry();
registry.register('xml', () => new XmlParser());
registry.register('yaml', () => new YamlParser());
registry.register('avro', () => new AvroParser());

async function processFile(path: string, data: AsyncIterable<Uint8Array>) {
  const ext = path.split('.').pop();
  const parser = registry.getParser(ext);
  if (!parser) throw new Error(`Unsupported format: ${ext}`);

  for await (const record of parser.parse(data)) {
    // Process record with backpressure handling
    await processRecord(record);
  }
}
```
